33		if err := ctx.Err(); err != nil {
34			return nil, err
35		}
36		if logDir == "" {
37			return nil, nil
38		}
39		entries, err := os.ReadDir(logDir)
40		if err != nil {
41			return nil, err
42		}
43		out := make([]SessionLogEntry, 0, len(entries))
44		for _, e := range entries {
45			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
46				continue
47			}
48			id := strings.TrimSuffix(e.Name(), ".jsonl")
49			entry := SessionLogEntry{SessionID: id}
50			if info, err := e.Info(); err == nil && info != nil {
51				entry.ModTime = info.ModTime()
52				entry.Size = info.Size()
53			}
54			out = append(out, entry)
